 public PeImage(byte[] bytes){Bytes=bytes;if(U16(0)!=0x5a4d)throw new Exception("Not PE");Pe=checked((int)U32(0x3c));if(U32(Pe)!=0x4550||U16(Pe+4)!=0x8664)throw new Exception("Only native x64 PE supported by generic builder");Sections=U16(Pe+6);OptSize=U16(Pe+20);Opt=Pe+24;if(U16(Opt)!=0x20b||OptSize<240||Sections<1||Sections>96)throw new Exception("Unsupported PE layout");SectionTable=Opt+OptSize;ExportRva=U32(Opt+112);ExportSize=U32(Opt+116);if(U32(Opt+112+14*8)!=0)throw new Exception("Managed PE cannot use native proxy rule");if(ExportRva==0)throw new Exception("Export table missing");int e=Map(ExportRva);ExportBase=U32(e+16);FunctionCount=U32(e+20);uint names=U32(e+24);if(FunctionCount==0||FunctionCount>10000||names>10000)throw new Exception("Unsupported export count");int functions=Map(U32(e+28)),nameTable=Map(U32(e+32)),ordinalTable=Map(U32(e+36));var byIndex=new Dictionary<int,string>();for(int i=0;i<names;i++){int index=U16(ordinalTable+i*2);if(index>=FunctionCount||byIndex.ContainsKey(index))throw new Exception("Aliased or invalid ordinal unsupported");byIndex[index]=Ascii(Map(U32(nameTable+i*4)));}for(int i=0;i<FunctionCount;i++){string name;byIndex.TryGetValue(i,out name);Symbols.Add(new ExportSymbol{Name=name,Ordinal=ExportBase+(uint)i,Address=U32(functions+i*4)});}}
 public ushort U16(int p){Bounds(p,2);return BitConverter.ToUInt16(Bytes,p);}public uint U32(int p){Bounds(p,4);return BitConverter.ToUInt32(Bytes,p);}void Bounds(int p,int n){if(p<0||p>Bytes.Length-n)throw new Exception("Invalid PE bounds");}
