public static class AutoBridge {
 public static string TemplateHash="2c74389f0bd4a323e39d9cd3edafe1526bb8e9cf598ae204bfd61c8b69b98367";
 static uint Align(uint v,uint a){if(a==0||(a&(a-1))!=0)throw new Exception("Invalid PE alignment");return checked((v+a-1)/a*a);}
